import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ __launch_bounds__(256) void sigmoid_kernel_fused(const float4* __restrict__ x4,
                                      float4* __restrict__ y4,
                                      const float* __restrict__ x,
                                      float* __restrict__ y,
                                      int n_vec4,
                                      int remainder,
                                      int remainder_start) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    const int UNROLL = 4;
    int big_stride = stride * UNROLL;
    for (int base = idx; base < n_vec4; base += big_stride) {
        #pragma unroll
        for (int u = 0; u < UNROLL; ++u) {
            int i = base + u * stride;
            if (i < n_vec4) {
                float4 v = __ldcs(&x4[i]);
                float4 r;
                r.x = __fdividef(1.0f, 1.0f + __expf(-v.x));
                r.y = __fdividef(1.0f, 1.0f + __expf(-v.y));
                r.z = __fdividef(1.0f, 1.0f + __expf(-v.z));
                r.w = __fdividef(1.0f, 1.0f + __expf(-v.w));
                __stcs(&y4[i], r);
            }
        }
    }
    for (int j = idx; j < remainder; j += stride) {
        int pos = remainder_start + j;
        __stcs(&y[pos], __fdividef(1.0f, 1.0f + __expf(-__ldcs(&x[pos]))));
    }
}
torch::Tensor sigmoid_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto y = torch::empty_like(x_contig);
    int64_t n = x_contig.numel();
    int64_t n_vec4 = n / 4;
    int64_t remainder_start = n_vec4 * 4;
    int64_t remainder = n - remainder_start;
    const float* x_ptr = x_contig.data_ptr<float>();
    float* y_ptr = y.data_ptr<float>();
    int64_t work_items = n_vec4 > remainder ? n_vec4 : remainder;
    if (work_items > 0) {
        const int threads = 256;
        static int64_t hw_blocks = 0;
        if (hw_blocks == 0) {
            int device = 0;
            cudaGetDevice(&device);
            int numSMs = 0;
            cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, device);
            int maxBlocksPerSM = 0;
            cudaOccupancyMaxActiveBlocksPerMultiprocessor(&maxBlocksPerSM, sigmoid_kernel_fused, threads, 0);
            hw_blocks = (int64_t)numSMs * (int64_t)(maxBlocksPerSM > 0 ? maxBlocksPerSM : 1);
            if (hw_blocks < 1) hw_blocks = 1;
        }
        int64_t needed_blocks = (work_items + threads - 1) / threads;
        int64_t chosen_blocks = needed_blocks < hw_blocks ? needed_blocks : hw_blocks;
        if (chosen_blocks < 1) chosen_blocks = 1;
        if (chosen_blocks > 65535) chosen_blocks = 65535;
        int blocks = (int)chosen_blocks;
        const float4* x4_ptr = reinterpret_cast<const float4*>(x_ptr);
        float4* y4_ptr = reinterpret_cast<float4*>(y_ptr);
        sigmoid_kernel_fused<<<blocks, threads>>>(
            x4_ptr, y4_ptr, x_ptr, y_ptr,
            (int)n_vec4, (int)remainder, (int)remainder_start);
    }
    return y;
}
"""

sigmoid_cpp_source = "torch::Tensor sigmoid_cuda(torch::Tensor x);"

sigmoid_module = load_inline(
    name="sigmoid_module",
    cpp_sources=sigmoid_cpp_source,
    cuda_sources=sigmoid_source,
    functions=["sigmoid_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Sigmoid activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.sigmoid_cuda = sigmoid_module.sigmoid_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.sigmoid_cuda(x)


